37	func (h *handler) register(w http.ResponseWriter, r *http.Request) {
38		var request struct {
39			ID   string `json:"id"`
40			Site string `json:"site"`
41		}
42		if err := decodeJSON(r, &request); err != nil || strings.TrimSpace(request.ID) == "" {
43			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
44			return
45		}
46		device, created, err := h.store.Register(strings.TrimSpace(request.ID), strings.TrimSpace(request.Site))
47		if errors.Is(err, ErrStorageUnavailable) {
48			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
49			return
50		}
51		if err != nil {
52			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
53			return
54		}
55		status := http.StatusOK
56		if created {
57			status = http.StatusCreated
58		}
59		writeJSON(w, status, device)
60	}
