62	func (h *handler) telemetry(w http.ResponseWriter, r *http.Request) {
63		values := map[string]float64{}
64		if err := decodeJSON(r, &values); err != nil || len(values) == 0 {
65			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values are required"})
66			return
67		}
68		if !finiteValues(values) {
