88	type replayRequest struct {
89		BatchID string `json:"batchId"`
90		Samples []struct {
91			EventID    string             `json:"eventId"`
92			ObservedAt string             `json:"observedAt"`
93			Values     map[string]float64 `json:"values"`
94		} `json:"samples"`
95	}
