259	func (h *handler) createRule(w http.ResponseWriter, r *http.Request) {
260		var request struct {
261			ID      string  `json:"id"`
262			Metric  string  `json:"metric"`
263			Trigger float64 `json:"trigger"`
264			Recover float64 `json:"recover"`
265		}
266		if err := decodeJSON(r, &request); err != nil {
267			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
268			return
269		}
270		ruleID := strings.TrimSpace(request.ID)
271		metric := strings.TrimSpace(request.Metric)
272		if ruleID == "" {
273			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
274			return
275		}
276		if metric == "" {
277			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric is required"})
278			return
279		}
280		if !finiteFloat(request.Trigger) || !finiteFloat(request.Recover) {
281			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "thresholds must be finite numbers"})
282			return
283		}
284		if request.Recover >= request.Trigger {
285			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
286			return
287		}
288		rule, err := h.store.CreateRule(r.PathValue("id"), ruleID, metric, request.Trigger, request.Recover)
289		if errors.Is(err, ErrDeviceNotFound) {
290			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
291			return
292		}
293		if errors.Is(err, ErrRuleConflict) {
294			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
295			return
296		}
297		if errors.Is(err, ErrStorageUnavailable) {
298			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
299			return
300		}
301		if err != nil {
302			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
303			return
304		}
305		writeJSON(w, http.StatusCreated, rule)
