100	// walReplay is one committed batch. Samples holds the full ordered batch
101	// (duplicates included) and Receipt the first-acceptance receipt; new events
102	// and their sequences are derived by zipping the two during recovery. Alerts
103	// and Ended carry the alert changes judged from the batch's new samples, in
104	// the same commit unit as the batch itself.
105	type walReplay struct {
106		DeviceID      string             `json:"deviceId"`
107		BatchID       string             `json:"batchId"`
108		Samples       []walSample        `json:"samples"`
109		Receipt       ReplayReceipt      `json:"receipt"`
110		LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
111		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
112		Alerts        []*Alert           `json:"alerts,omitempty"`
113		Ended         []*Alert           `json:"ended,omitempty"`
114	}
