		t.Fatalf("filtered events = %+v, want sequences 2,3", resp.Events)
	}

	for name, target := range map[string]string{
		"inverted range": "/v1/devices/gw/history?from=2024-01-03T00:00:00Z&to=2024-01-01T00:00:00Z",
