286	func TestRuleConcurrentUpdatesOneWins(t *testing.T) {
287		h := NewHandler(NewStore())
288		mustRegister(t, h, "gw")
289		createRule(t, h, "gw", "r1", "temperature", 30, 25)
290	
291		const callers = 12
292		var start, wg sync.WaitGroup
293		start.Add(1)
294		codes := make([]int, callers)
295		wg.Add(callers)
296		for i := 0; i < callers; i++ {
297			go func(i int) {
298				defer wg.Done()
299				start.Wait()
300				r := doRequest(t, h, http.MethodPut, "/v1/devices/gw/rules/r1",
301					`{"trigger":35,"recover":28,"version":1}`)
302				codes[i] = r.Code
303			}(i)
304		}
305		start.Done()
306		wg.Wait()
307	
308		ok, conflict := 0, 0
309		for _, code := range codes {
310			switch code {
311			case http.StatusOK:
312				ok++
313			case http.StatusConflict:
314				conflict++
315			default:
316				t.Errorf("unexpected status %d", code)
317			}
318		}
319		if ok != 1 || conflict != callers-1 {
320			t.Fatalf("codes = %d ok / %d conflict, want 1/%d", ok, conflict, callers-1)
321		}
322		after := decodeBody[ruleResponse](t, doRequest(t, h, http.MethodGet, "/v1/devices/gw/rules/r1", ""))
323		if after.Version != 2 {
324			t.Fatalf("version = %d, want 2", after.Version)
325		}
326	}
